22:     /// @dev Returns the address where a contract will be stored if deployed via
23:     /// `deployer` with `nonce` using the `CREATE` opcode.
24:     /// For the specification of the Recursive Length Prefix (RLP)
25:     /// encoding scheme, please refer to p. 19 of the Ethereum Yellow Paper
26:     /// (https://ethereum.github.io/yellowpaper/paper.pdf)
27:     /// and the Ethereum Wiki (https://eth.wiki/fundamentals/rlp).
28:     ///
29:     /// Based on the EIP-161 (https://github.com/ethereum/EIPs/blob/master/EIPS/eip-161.md)
30:     /// specification, all contract accounts on the Ethereum mainnet are initiated with
31:     /// `nonce = 1`. Thus, the first contract address created by another contract
32:     /// is calculated with a non-zero nonce.
33:     ///
34:     /// The theoretical allowed limit, based on EIP-2681
35:     /// (https://eips.ethereum.org/EIPS/eip-2681), for an account nonce is 2**64-2.
36:     ///
37:     /// Caution! This function will NOT check that the nonce is within the theoretical range.
38:     /// This is for performance, as exceeding the range is extremely impractical.
39:     /// It is the user's responsibility to ensure that the nonce is valid
40:     /// (e.g. no dirty bits after packing / unpacking).
41:     ///
42:     /// This is equivalent to:
43:     /// `address(uint160(uint256(keccak256(LibRLP.p(deployer).p(nonce).encode()))))`.
44:     ///
45:     /// Note: The returned result has dirty upper 96 bits. Please clean if used in assembly.
46:     function computeAddress(address deployer, uint256 nonce)
47:         internal
48:         pure
49:         returns (address deployed)
50:     {
51:         /// @solidity memory-safe-assembly
52:         assembly {
53:             for {} 1 {} {
54:                 // The integer zero is treated as an empty byte string,
55:                 // and as a result it only has a length prefix, 0x80,
56:                 // computed via `0x80 + 0`.
57: 
58:                 // A one-byte integer in the [0x00, 0x7f] range uses its
59:                 // own value as a length prefix,
60:                 // there is no additional `0x80 + length` prefix that precedes it.
61:                 if iszero(gt(nonce, 0x7f)) {
62:                     mstore(0x00, deployer)
63:                     // Using `mstore8` instead of `or` naturally cleans
64:                     // any dirty upper bits of `deployer`.
65:                     mstore8(0x0b, 0x94)
66:                     mstore8(0x0a, 0xd6)
67:                     // `shl` 7 is equivalent to multiplying by 0x80.
68:                     mstore8(0x20, or(shl(7, iszero(nonce)), nonce))
69:                     deployed := keccak256(0x0a, 0x17)
70:                     break
71:                 }
72:                 let i := 8
73:                 // Just use a loop to generalize all the way with minimal bytecode size.
74:                 for {} shr(i, nonce) { i := add(i, 8) } {}
75:                 // `shr` 3 is equivalent to dividing by 8.
76:                 i := shr(3, i)
77:                 // Store in descending slot sequence to overlap the values correctly.
78:                 mstore(i, nonce)
79:                 mstore(0x00, shl(8, deployer))
80:                 mstore8(0x1f, add(0x80, i))
81:                 mstore8(0x0a, 0x94)
82:                 mstore8(0x09, add(0xd6, i))
83:                 deployed := keccak256(0x09, add(0x17, i))
84:                 break
85:             }
86:         }
87:     }
