    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Writes the provided data to a new contract and returns the contract's address.
    /// @dev This function uses inline assembly to deploy a new contract with the provided data.
    /// The data is prefixed with a STOP opcode to ensure the contract cannot be called directly.
    /// @param data The bytecode data to be written to the new contract.
    /// @return pointer The address of the newly deployed contract.
    function write(bytes memory data) internal returns (address pointer) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(data) // Load the length of the data.

            // Prefix the data with a STOP opcode (0x00) to prevent direct calls.
            // The deployed contract's runtime code will be: 0x00 ++ data.
            // The initialization code is:
            // - PUSH1 0x00 (STOP opcode value)
            // - PUSH1 0x1c (offset where data starts in memory after prepending init code)
            // - PUSH1 0x00 (offset for memory read)
            // - CALLDATASIZE (length of data to copy - we use this trick to get n)
            // Actually, the standard SSTORE2 pattern:
            // Store STOP (0x00) at memory position data_start - 1
            // Then use CREATE with initCode that returns memory[data_start-1 .. data_start-1+n+1]
            // The initCode is: PUSH1 0x01 PUSH1 0x00 RETURN (return 1 byte at offset 0)
            // But that's not right for storing the data.

            // Standard SSTORE2 implementation:
            // 1. Store 0x00 at mload(data) - 1 position (prepend STOP to data in memory)
            // 2. Deploy with initCode that is PUSH1(len+1) PUSH1(offset) RETURN
            // This makes the runtime code = 0x00 ++ data

            // We need to prepend the init code header to the data.
            // Init code header: 0x61000000 + data_length_as_2_bytes + 0x3d + 0x82 + 0x6000 + 0x39 + 0x3d + 0xf3
            // Actually let's use the simpler approach used in Solmate/Solady SSTORE2

            // Store STOP (0x00) right before the data in memory
            mstore8(add(data, 0x1f), 0x00) // Store 0x00 right before the data bytes

            // The initCode should return memory[0x1f..0x1f+n+1] which is 0x00 ++ data
            // InitCode: PUSH2(n+1) PUSH1(0x1f) PUSH1(0x00) CODECOPY PUSH2(n+1) PUSH1(0x00) RETURN
            // Actually the standard pattern is:
            // 0x61 + n_hi + n_lo  (PUSH2 for size)
            // 0x60 0x1f           (PUSH1 for offset 0x1f)
            // 0x3d                (RETURNDATASIZE = 0, for destOffset)
            // 0x39                (CODECOPY)
