            // 60 XX = PUSH1(code_size, where data starts)  
            // 3d = RETURNDATASIZE (0)
            // 39 = CODECOPY(0, code_size, n+1)
            // 3d = RETURNDATASIZE (0)
            // f3 = RETURN(0, n+1) -- but wait RETURN needs (offset, size) and size should be on top
            // After CODECOPY: stack is empty, memory[0..n+1] has the data
            // We need RETURN(0, n+1)
            // 60 00 = PUSH1(0) -- return offset
            // ... but where does n+1 come from?

            // I think the pattern is actually:
            // 61 XX XX = PUSH2(n+1) -> [n+1]  
            // 80 = DUP1 -> [n+1, n+1]
            // 60 XX = PUSH1(offset) -> [offset, n+1, n+1]
            // 3d = RETURNDATASIZE -> [0, offset, n+1, n+1]
