            // data+0x20: data[0]
            // ...

            // Total init code size = 9 (prefix) + 1 (STOP) + n (data) = 10 + n
            // CREATE(0, data+0x16, 10+n)

            // Now I need to encode this in assembly.

            // n_plus_1 = n + 1
            // Store 0x61 at data+0x16
            // Store n_plus_1 shifted left appropriately at data+0x17 (2 bytes)
            // Store 0x60093d393df3 as a 6-byte sequence at data+0x19

            // Actually, let me encode the whole prefix as a single 256-bit value and use mstore:
            // prefix = 0x61 XX XX 60 09 3d 39 3d f3 00 00 ... 00 (32 bytes, right-padded)
            // where XX XX = (n+1) as big-endian 2 bytes

            // Let me construct this:
            // base = 0x61000060093d393df300...00
            // Then OR with (n+1) << (32 - 3) * 8 = (n+1) << 232... wait
            // Byte positions (0-indexed from MSB):
            // Byte 0: 0x61
            // Byte 1: (n+1) >> 8
            // Byte 2: (n+1) & 0xff
            // Byte 3: 0x60
            // Byte 4: 0x09
            // Byte 5: 0x3d
            // Byte 6: 0x39
            // Byte 7: 0x3d
            // Byte 8: 0xf3

            // So the 9-byte prefix as a uint256 (left-aligned in 32 bytes):
            // shl(184, 0x61) | shl(176, n_hi) | shl(168, n_lo) | shl(160, 0x60) | shl(152, 0x09) | shl(144, 0x3d) | shl(136, 0x39) | shl(128, 0x3d) | shl(120, 0xf3)
            // = 0x61000060093d393df3 << 184... no

            // Actually simpler: 
            // mstore(add(data, 0x16), shl(184, or(0x61000060093d393df300, shl(8, add(n, 1)))))
            // Hmm this is getting messy. Let me just do it step by step.

            // Store the prefix byte by byte or in chunks
            // Actually, I can store the whole thing as one mstore with careful bit manipulation.

            // Store the fixed prefix bytes at data + 0x16:
            // Position data+0x16: 0x61
            mstore8(add(data, 0x16), 0x61)
            // Position data+0x19: 0x60
            mstore8(add(data, 0x19), 0x60)
            // Position data+0x1a: 0x09
            mstore8(add(data, 0x1a), 0x09)
            // Position data+0x1b: 0x3d
            mstore8(add(data, 0x1b), 0x3d)
            // Position data+0x1c: 0x39
            mstore8(add(data, 0x1c), 0x39)
            // Position data+0x1d: 0x3d
            mstore8(add(data, 0x1d), 0x3d)
            // Position data+0x1e: 0xf3
            mstore8(add(data, 0x1e), 0xf3)
            // Store n+1 as big-endian 2 bytes at data+0x17
            mstore(add(data, 0x17), shl(232, add(n, 1)))
            // Store 0x00 (STOP prefix) at data+0x1f
            mstore8(add(data, 0x1f), 0x00)

            // Deploy with CREATE
            pointer := create(0, add(data, 0x16), add(10, n))

            // Revert if deployment failed
            if iszero(pointer) {
                mstore(0x00, 0x30116425) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }
        }
    }

    function writeCounterfactual(bytes memory data, bytes32 salt) internal returns (address pointer) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(data)

            // Store the prefix and STOP byte (same as write)
            mstore8(add(data, 0x16), 0x61)
            mstore8(add(data, 0x19), 0x60)
            mstore8(add(data, 0x1a), 0x09)
            mstore8(add(data, 0x1b), 0x3d)
            mstore8(add(data, 0x1c), 0x39)
            mstore8(add(data, 0x1d), 0x3d)
            mstore8(add(data, 0x1e), 0xf3)
            mstore(add(data, 0x17), shl(232, add(n, 1)))
            mstore8(add(data, 0x1f), 0x00)

            pointer := create2(0, add(data, 0x16), add(10, n), salt)

            if iszero(pointer) {
                mstore(0x00, 0x30116425) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }
        }
    }

    function writeDeterministic(bytes memory data, bytes32 salt) internal returns (address pointer) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(data)

            // Deploy proxy using CREATE2
            mstore(0x00, _CREATE3_PROXY_INITCODE)
            let proxy := create2(0, 0x10, 0x10, salt)
            if iszero(proxy) {
                mstore(0x00, 0x30116425) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }

            // Store proxy address and compute the deterministic address
            mstore(0x14, proxy)
            mstore(0x00, 0xd694)
            mstore8(0x34, 0x01)
            pointer := keccak256(0x1e, 0x17)

            // Ensure data length + 1 does not exceed 2 bytes
            if gt(add(n, 1), 0xffff) {
                mstore(0x00, 0x30116425) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }

            // Prepare the data to send to the proxy
            // Store 0x00 prefix before data
            mstore8(add(data, 0x1f), 0x00)

            // Call the proxy with the data (including STOP prefix)
            if iszero(
                and(
                    extcodesize(pointer),
                    call(gas(), proxy, 0, add(data, 0x20), n, 0x00, 0x00)
                )
            ) {
                mstore(0x00, 0x30116425) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }
        }
    }

    /// @notice Computes the keccak256 hash of the given bytecode data with a specific prefix.
    /// @param data The bytecode data to compute the hash for.
    /// @return hash The computed keccak256 hash of the modified data.
    function initCodeHash(bytes memory data) internal pure returns (bytes32 hash) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(data)

            // Store the creation code prefix
            mstore8(add(data, 0x16), 0x61)
            mstore8(add(data, 0x19), 0x60)
            mstore8(add(data, 0x1a), 0x09)
            mstore8(add(data, 0x1b), 0x3d)
            mstore8(add(data, 0x1c), 0x39)
            mstore8(add(data, 0x1d), 0x3d)
            mstore8(add(data, 0x1e), 0xf3)
            mstore(add(data, 0x17), shl(232, add(n, 1)))
            mstore8(add(data, 0x1f), 0x00)

            hash := keccak256(add(data, 0x16), add(10, n))
        }
    }

    function predictCounterfactualAddress(bytes memory data, bytes32 salt) internal view returns (address pointer) {
        pointer = predictCounterfactualAddress(data, salt, address(this));
    }

    function predictCounterfactualAddress(bytes memory data, bytes32 salt, address deployer) internal pure returns (address predicted) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(data)

            // Store the creation code prefix
            mstore8(add(data, 0x16), 0x61)
            mstore8(add(data, 0x19), 0x60)
            mstore8(add(data, 0x1a), 0x09)
            mstore8(add(data, 0x1b), 0x3d)
            mstore8(add(data, 0x1c), 0x39)
            mstore8(add(data, 0x1d), 0x3d)
            mstore8(add(data, 0x1e), 0xf3)
            mstore(add(data, 0x17), shl(232, add(n, 1)))
            mstore8(add(data, 0x1f), 0x00)

            // Compute CREATE2 address: keccak256(0xff ++ deployer ++ salt ++ keccak256(initCode))[12:]
            mstore(0x00, deployer)
            mstore8(0x0b, 0xff)
            mstore(0x20, salt)
            mstore(0x40, keccak256(add(data, 0x16), add(10, n)))
            predicted := keccak256(0x0b, 0x55)
        }
    }

    /// @notice Predicts the deterministic address for a contract deployment using CREATE3.
    /// @param salt A unique salt value used to generate the deterministic address.
    /// @return pointer The predicted deterministic address for the contract deployment.
    function predictDeterministicAddress(bytes32 salt) internal view returns (address pointer) {
        pointer = predictDeterministicAddress(salt, address(this));
    }

    /// @notice Predicts the deterministic address for a contract deployment using CREATE3.
    /// @param salt A unique salt value used to generate the deterministic address.
    /// @param deployer The address of the deployer that will deploy the contract.
    /// @return pointer The predicted deterministic address for the contract deployment.
    function predictDeterministicAddress(bytes32 salt, address deployer) internal pure returns (address pointer) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40) // Cache the free memory pointer.
            mstore(0x00, deployer)
            mstore8(0x0b, 0xff)
            mstore(0x20, salt)
            mstore(0x40, _CREATE3_PROXY_INITCODE_HASH)

            mstore(0x14, keccak256(0x0b, 0x55)) // Compute proxy address.
            mstore(0x40, m) // Restore the free memory pointer.
            // 0xd6 = 0xc0 (short RLP prefix) + 0x16 (length of: 0x94 ++ proxy ++ 0x01).
            // 0x94 = 0x80 + 0x14 (0x14 = the length of an address, 20 bytes, in hex).
            mstore(0x00, 0xd694)
            mstore8(0x34, 0x01) // Nonce of the proxy contract (1).
            pointer := keccak256(0x1e, 0x17)
        }
    }

    /// @notice Reads the code of a contract at the given address and returns it as a byte array.
    /// @param pointer The address of the contract whose code is to be read.
    /// @return data A byte array containing the contract's code.
    function read(address pointer) internal view returns (bytes memory data) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := extcodesize(pointer)
            data := mload(0x40)
            // Store the length.
            mstore(data, n)
            // Copy the code, skipping the first byte (STOP prefix).
            extcodecopy(pointer, add(data, 0x21), 0x01, n)
            // Zeroize the slot after the data.
            mstore(add(add(data, 0x20), n), 0)
            // Update the free memory pointer.
            mstore(0x40, and(add(add(data, 0x40), n), not(0x1f)))
        }
    }

    /// @notice Reads the code of a contract at the given address starting from a position.
    /// @param pointer The address of the contract whose code is to be read.
    /// @param start The start position to read from.
    /// @return data A byte array containing the contract's code from the start position.
    function read(address pointer, uint256 start) internal view returns (bytes memory data) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := extcodesize(pointer)
            // If start >= n, return empty bytes.
            if lt(start, n) {
                // The actual data length = n - 1 (subtracting the STOP prefix byte).
                // We read from position (1 + start) because position 0 is the STOP prefix.
                let toRead := sub(n, add(1, start))
                data := mload(0x40)
                mstore(data, toRead)
                extcodecopy(pointer, add(data, 0x21), add(0x01, start), toRead)
                mstore(add(add(data, 0x20), toRead), 0)
                mstore(0x40, and(add(add(data, 0x40), toRead), not(0x1f)))
            }
        }
    }

    /// @notice Reads the code of a contract at the given address from start to end.
    /// @param pointer The address of the contract whose code is to be read.
    /// @param start The start position to read from.
    /// @param end The end position (exclusive) to read to.
    /// @return data A byte array containing the contract's code from start to end.
    function read(address pointer, uint256 start, uint256 end) internal view returns (bytes memory data) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := extcodesize(pointer)
            // If start < end and end <= n-1 (actual data length = n-1).
            if and(lt(start, end), lt(end, n)) {
                let toRead := sub(end, start)
                data := mload(0x40)
                mstore(data, toRead)
                extcodecopy(pointer, add(data, 0x21), add(0x01, start), toRead)
                mstore(add(add(data, 0x20), toRead), 0)
                mstore(0x40, and(add(add(data, 0x40), toRead), not(0x1f)))
            }
        }
    }
}

