    /// @dev This function uses inline assembly to deploy a new contract with the provided data.
    /// The data is prefixed with a STOP opcode to ensure the contract cannot be called directly.
    /// @param data The bytecode data to be written to the new contract.
    /// @return pointer The address of the newly deployed contract.
    function write(bytes memory data) internal returns (address pointer) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(data)
            // The runtime code will be: 0x00 ++ data (length n+1).
            // The init code prefix (9 bytes) uses CODECOPY to copy the data portion
            // from the init code to memory, then RETURN to set it as runtime code.
            // Init code: PUSH2(n+1) PUSH1(0x09) RETURNDATASIZE CODECOPY RETURNDATASIZE RETURN
            // = 61 XX XX 60 09 3d 39 3d f3
            // Then 0x00 (STOP) followed by data bytes.
            // Stored at memory positions data+0x16 through data+0x1f+n.
            mstore8(add(data, 0x16), 0x61)
            mstore8(add(data, 0x17), shr(8, add(n, 1)))
            mstore8(add(data, 0x18), and(add(n, 1), 0xff))
            mstore8(add(data, 0x19), 0x60)
            mstore8(add(data, 0x1a), 0x09)
            mstore8(add(data, 0x1b), 0x3d)
            mstore8(add(data, 0x1c), 0x39)
            mstore8(add(data, 0x1d), 0x3d)
            mstore8(add(data, 0x1e), 0xf3)
            mstore8(add(data, 0x1f), 0x00) // STOP prefix for runtime code.
            pointer := create(0, add(data, 0x16), add(10, n))
            if iszero(pointer) {
                mstore(0x00, 0x30116425) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }
        }
