    /// @param pointer The address of the contract whose code is to be read.
    /// @param start The start position to read from.
    /// @return data A byte array containing the contract's code from the start position.
    function read(address pointer, uint256 start) internal view returns (bytes memory data) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := sub(extcodesize(pointer), 1)
            if lt(start, n) {
                let toRead := sub(n, start)
                data := mload(0x40)
                mstore(data, toRead)
                extcodecopy(pointer, add(data, 0x21), add(0x01, start), toRead)
