    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                      BYTECODE CONSTANTS                    */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev The proxy initialization code for CREATE3.
    uint256 private constant _CREATE3_PROXY_INITCODE = 0x67363d3d37363d34f03d5260086018f3;

    /// @dev Hash of the `_CREATE3_PROXY_INITCODE`.
    bytes32 private constant _CREATE3_PROXY_INITCODE_HASH =
        0x21c35dbe1b344a2488cf3321d6ce542f8e9f305544ff09e4993a62319a497c1f;

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                       SSTORE2 OPERATIONS                   */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Writes the provided data to a new contract and returns the contract's address.
    /// @dev This function uses inline assembly to deploy a new contract with the provided data.
    /// The data is prefixed with a STOP opcode to ensure the contract cannot be called directly.
    /// @param data The bytecode data to be written to the new contract.
    /// @return pointer The address of the newly deployed contract.
    function write(bytes memory data) internal returns (address pointer) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(data)
            // The runtime code will be: 0x00 ++ data (length n+1).
            // The init code prefix (9 bytes) uses CODECOPY to copy the data portion
            // from the init code to memory, then RETURN to set it as runtime code.
            // Init code: PUSH2(n+1) PUSH1(0x09) RETURNDATASIZE CODECOPY RETURNDATASIZE RETURN
            // = 61 XX XX 60 09 3d 39 3d f3
            // Then 0x00 (STOP) followed by data bytes.
            // Stored at memory positions data+0x16 through data+0x1f+n.
            mstore8(add(data, 0x16), 0x61)
            mstore8(add(data, 0x17), shr(8, add(n, 1)))
            mstore8(add(data, 0x18), and(add(n, 1), 0xff))
            mstore8(add(data, 0x19), 0x60)
            mstore8(add(data, 0x1a), 0x09)
            mstore8(add(data, 0x1b), 0x3d)
            mstore8(add(data, 0x1c), 0x39)
            mstore8(add(data, 0x1d), 0x3d)
            mstore8(add(data, 0x1e), 0xf3)
            mstore8(add(data, 0x1f), 0x00) // STOP prefix for runtime code.
            pointer := create(0, add(data, 0x16), add(10, n))
            if iszero(pointer) {
                mstore(0x00, 0x30116425) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }
        }
    }

    /// @notice Deploys a new contract using the `create2` opcode with the provided data and salt.
    /// @param data The bytecode and constructor arguments for the contract to be deployed.
    /// @param salt A unique value used to determine the contract's address.
    /// @return pointer The address of the newly deployed contract.
    function writeCounterfactual(bytes memory data, bytes32 salt) internal returns (address pointer) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(data)
            mstore8(add(data, 0x16), 0x61)
            mstore8(add(data, 0x17), shr(8, add(n, 1)))
            mstore8(add(data, 0x18), and(add(n, 1), 0xff))
            mstore8(add(data, 0x19), 0x60)
            mstore8(add(data, 0x1a), 0x09)
            mstore8(add(data, 0x1b), 0x3d)
            mstore8(add(data, 0x1c), 0x39)
            mstore8(add(data, 0x1d), 0x3d)
            mstore8(add(data, 0x1e), 0xf3)
            mstore8(add(data, 0x1f), 0x00)
            pointer := create2(0, add(data, 0x16), add(10, n), salt)
            if iszero(pointer) {
                mstore(0x00, 0x30116425) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }
        }
    }

    /// @notice Deploys a deterministic proxy contract using CREATE2 and initializes it with the provided data.
    /// @param data The data to be passed to the proxy contract for initialization.
    /// @param salt A unique salt value used to determine the address of the deployed proxy contract.
    /// @return pointer The address of the deployed proxy contract.
    function writeDeterministic(bytes memory data, bytes32 salt) internal returns (address pointer) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(data)
            // Deploy proxy using CREATE2.
            mstore(0x00, _CREATE3_PROXY_INITCODE)
            let proxy := create2(0, 0x10, 0x10, salt)
            if iszero(proxy) {
                mstore(0x00, 0x30116425) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }
            // Compute the deterministic address of the contract the proxy will deploy.
            // The proxy address is used as the deployer with nonce 1.
            mstore(0x14, proxy) // Store the proxy's address.
            // 0xd6 = 0xc0 (short RLP prefix) + 0x16 (length of: 0x94 ++ proxy ++ 0x01).
            // 0x94 = 0x80 + 0x14 (0x14 = the length of an address, 20 bytes, in hex).
            mstore(0x00, 0xd694)
            mstore8(0x34, 0x01) // Nonce of the proxy contract (1).
            pointer := keccak256(0x1e, 0x17)
            // Ensure data length + 1 does not exceed 2 bytes.
            if gt(add(n, 1), 0xffff) {
                mstore(0x00, 0x30116425) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }
            // Prepare the init code for the data (runtime code = 0x00 ++ data).
            mstore8(add(data, 0x16), 0x61)
            mstore8(add(data, 0x17), shr(8, add(n, 1)))
            mstore8(add(data, 0x18), and(add(n, 1), 0xff))
            mstore8(add(data, 0x19), 0x60)
            mstore8(add(data, 0x1a), 0x09)
            mstore8(add(data, 0x1b), 0x3d)
            mstore8(add(data, 0x1c), 0x39)
            mstore8(add(data, 0x1d), 0x3d)
            mstore8(add(data, 0x1e), 0xf3)
            mstore8(add(data, 0x1f), 0x00)
            // Send the init code to the proxy. The proxy will CREATE with it.
            if iszero(
                mul( // The arguments of `mul` are evaluated last to first.
                    extcodesize(pointer),
                    call(gas(), proxy, 0, add(data, 0x16), add(10, n), 0x00, 0x00)
                )
            ) {
                mstore(0x00, 0x30116425) // `DeploymentFailed()`.
                revert(0x1c, 0x04)
            }
        }
    }

    /// @notice Computes the keccak256 hash of the given bytecode data with a specific prefix.
    /// @param data The bytecode data to compute the hash for.
    /// @return hash The computed keccak256 hash of the modified data.
    function initCodeHash(bytes memory data) internal pure returns (bytes32 hash) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(data)
            mstore8(add(data, 0x16), 0x61)
            mstore8(add(data, 0x17), shr(8, add(n, 1)))
            mstore8(add(data, 0x18), and(add(n, 1), 0xff))
            mstore8(add(data, 0x19), 0x60)
            mstore8(add(data, 0x1a), 0x09)
            mstore8(add(data, 0x1b), 0x3d)
            mstore8(add(data, 0x1c), 0x39)
            mstore8(add(data, 0x1d), 0x3d)
            mstore8(add(data, 0x1e), 0xf3)
            mstore8(add(data, 0x1f), 0x00)
            hash := keccak256(add(data, 0x16), add(10, n))
        }
    }

    /// @notice Predicts the counterfactual address for a contract deployment using the provided data and salt.
    /// @param data The bytecode or initialization data for the contract.
    /// @param salt A unique value used to influence the resulting address.
    /// @return pointer The predicted address of the contract if deployed with the given data and salt.
    function predictCounterfactualAddress(bytes memory data, bytes32 salt)
        internal
        view
        returns (address pointer)
    {
        pointer = predictCounterfactualAddress(data, salt, address(this));
    }

    /// @notice Predicts the counterfactual address for a contract deployment using the provided data and salt.
    /// @param data The bytecode or initialization data for the contract.
    /// @param salt A unique value used to influence the resulting address.
    /// @param deployer The address of the deployer that will deploy the contract.
    /// @return predicted The predicted address of the contract if deployed with the given data and salt.
    function predictCounterfactualAddress(bytes memory data, bytes32 salt, address deployer)
        internal
        pure
        returns (address predicted)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(data)
            mstore8(add(data, 0x16), 0x61)
            mstore8(add(data, 0x17), shr(8, add(n, 1)))
            mstore8(add(data, 0x18), and(add(n, 1), 0xff))
            mstore8(add(data, 0x19), 0x60)
            mstore8(add(data, 0x1a), 0x09)
            mstore8(add(data, 0x1b), 0x3d)
            mstore8(add(data, 0x1c), 0x39)
            mstore8(add(data, 0x1d), 0x3d)
            mstore8(add(data, 0x1e), 0xf3)
            mstore8(add(data, 0x1f), 0x00)
            // Compute CREATE2 address: keccak256(0xff ++ deployer ++ salt ++ keccak256(initCode))[12:]
            mstore(0x00, deployer)
            mstore8(0x0b, 0xff)
            mstore(0x20, salt)
            mstore(0x40, keccak256(add(data, 0x16), add(10, n)))
            predicted := keccak256(0x0b, 0x55)
        }
    }

    /// @notice Predicts the deterministic address for a contract deployment using CREATE3.
    /// @param salt A unique salt value used to generate the deterministic address.
    /// @return pointer The predicted deterministic address for the contract deployment.
    function predictDeterministicAddress(bytes32 salt) internal view returns (address pointer) {
        pointer = predictDeterministicAddress(salt, address(this));
    }

    /// @notice Predicts the deterministic address for a contract deployment using CREATE3.
    /// @param salt A unique salt value used to generate the deterministic address.
    /// @param deployer The address of the deployer that will deploy the contract.
    /// @return pointer The predicted deterministic address for the contract deployment.
    function predictDeterministicAddress(bytes32 salt, address deployer)
        internal
        pure
        returns (address pointer)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40) // Cache the free memory pointer.
            mstore(0x00, deployer)
            mstore8(0x0b, 0xff)
            mstore(0x20, salt)
            mstore(0x40, _CREATE3_PROXY_INITCODE_HASH)
            mstore(0x14, keccak256(0x0b, 0x55)) // Store the proxy's address.
            mstore(0x40, m) // Restore the free memory pointer.
            // 0xd6 = 0xc0 (short RLP prefix) + 0x16 (length of: 0x94 ++ proxy ++ 0x01).
            // 0x94 = 0x80 + 0x14 (0x14 = the length of an address, 20 bytes, in hex).
            mstore(0x00, 0xd694)
            mstore8(0x34, 0x01) // Nonce of the proxy contract (1).
            pointer := keccak256(0x1e, 0x17)
        }
    }

    /// @notice Reads the code of a contract at the given address and returns it as a byte array.
    /// @param pointer The address of the contract whose code is to be read.
    /// @return data A byte array containing the contract's code (without the STOP prefix).
    function read(address pointer) internal view returns (bytes memory data) {
        /// @solidity memory-safe-assembly
        assembly {
            // The runtime code is 0x00 ++ data. We skip the first byte (STOP prefix).
            let n := sub(extcodesize(pointer), 1)
            data := mload(0x40)
            mstore(data, n)
            extcodecopy(pointer, add(data, 0x21), 0x01, n)
            mstore(add(add(data, 0x20), n), 0)
            mstore(0x40, and(add(add(data, 0x40), n), not(0x1f)))
        }
    }

    /// @notice Reads the code of a contract at the given address starting from a position.
    /// @param pointer The address of the contract whose code is to be read.
    /// @param start The start position to read from.
    /// @return data A byte array containing the contract's code from the start position.
    function read(address pointer, uint256 start) internal view returns (bytes memory data) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := sub(extcodesize(pointer), 1)
            if lt(start, n) {
                let toRead := sub(n, start)
                data := mload(0x40)
                mstore(data, toRead)
                extcodecopy(pointer, add(data, 0x21), add(0x01, start), toRead)
                mstore(add(add(data, 0x20), toRead), 0)
                mstore(0x40, and(add(add(data, 0x40), toRead), not(0x1f)))
            }
        }
    }

    /// @notice Reads the code of a contract at the given address from start to end.
    /// @param pointer The address of the contract whose code is to be read.
    /// @param start The start position to read from.
    /// @param end The end position (exclusive) to read to.
    /// @return data A byte array containing the contract's code from start to end.
    function read(address pointer, uint256 start, uint256 end) internal view returns (bytes memory data) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := sub(extcodesize(pointer), 1)
            if lt(start, end) {
                if gt(end, n) { end := n }
                if lt(start, end) {
                    let toRead := sub(end, start)
                    data := mload(0x40)
                    mstore(data, toRead)
                    extcodecopy(pointer, add(data, 0x21), add(0x01, start), toRead)
                    mstore(add(add(data, 0x20), toRead), 0)
                    mstore(0x40, and(add(add(data, 0x40), toRead), not(0x1f)))
                }
            }
        }
    }
}
